from typing import Callable
from event import Event

def sanitize_middleware(event: Event) -> Event:
    cleaned = dict(event.payload)
    cleaned.pop("password", None)
    return Event(name=event.name, payload=cleaned, tags=list(event.tags))

def tagging_middleware(event: Event) -> Event:
    tags = list(event.tags) + ["processed"]
    return Event(name=event.name, payload=dict(event.payload), tags=tags)

