from typing import List, Callable, Dict
from event import Event

class EventBus:
    def __init__(self):
        self.middlewares: List[Callable[[Event], Event]] = []
        self.subscribers: Dict[str, List[Callable[[Event], None]]] = {}

    def use(self, mw: Callable[[Event], Event]) -> None:
        self.middlewares.append(mw)

    def subscribe(self, event_name: str, handler: Callable[[Event], None]) -> None:
        self.subscribers.setdefault(event_name, []).append(handler)

    def publish(self, event: Event) -> None:
        current_event = event
        for mw in self.middlewares:
            # Bug: calls mw(event) without reassigning current_event
            mw(event)

        for handler in self.subscribers.get(current_event.name, []):
            handler(current_event)

